/// Sum of all values.
/// BUG: sums into u32 first, then widens - overflows past u32::MAX (~4.29e9);
/// debug builds panic, release builds wrap.
pub fn total(values: &[u32]) -> u64 {
    values.iter().copied().sum::<u32>() as u64
}

test_setup_files.tests/total_test.rs:
use sum_total::total;

#[test]
fn sums_small() {
    assert_eq!(total(&[1, 2, 3]), 6);
}

#[test]
fn empty_is_zero() {
    assert_eq!(total(&[]), 0);
}

#[test]
fn sums_large_without_overflow() {
    // 3_000_000_000 + 2_000_000_000 = 5_000_000_000 > u32::MAX
    assert_eq!(total(&[3_000_000_000, 2_000_000_000]), 5_000_000_000);
}

#[test]
fn sums_many_large_values() {
    let values = vec![4_000_000_000u32; 3]; // 1.2e10
    assert_eq!(total(&values), 12_000_000_000);
}

