/// Stops panicking but still accumulates in u32 via wrapping_add, so the
/// result wraps modulo 2^32 for large inputs.
pub fn total(values: &[u32]) -> u64 {
    values.iter().copied().fold(0u32, |acc, x| acc.wrapping_add(x)) as u64
}
